local function power(u,id) local v,m=unit(u,"get_power",id),unit(u,"get_max_power",id);return tonumber(v) or 0,tonumber(m) or 0 end
local function mana(u) local v,m=power(u,0);return m>0 and v/m*100 or 100 end
