  if type(id)=="number" and known(id) then local n=static(C.spell_book,"get_spell_name",id);local k=type(n)=="string" and reverse[n:lower()];if k then
   learned_names[k]=learned_names[k] or {};table.insert(learned_names[k],id)
  end end
