end
local function aura(u,id,debuff,own)
 for _,a in pairs(unit(u,debuff and "get_debuffs" or "get_buffs") or {}) do
  if a.buff_id==id and (not own or same(a.caster,State.me)) then
   local expiry=tonumber(a.expire_time) or 0
   return expiry>0 and math.max(0,expiry-now()) or 999,a.count or 1
  end
 end
