local Settings={}
local bool_defaults={enabled=true,damage=true,healing=true,cooldowns=true,defensives=true,interrupts=true,dispel=true,aoe=true,multidot=true,buffs=true,pvp_cc=false,predictive=true}
local num_defaults={emergency=35,heal_at=86,damage_above=88,mana_reserve=20,defensive_at=45,aoe_count=3,max_dots=5,mode=1}
local Identity={spec=C.menu.slider_int(1,4,1,"pt100_identity_spec"),client=C.menu.slider_int(1,3,1,"pt100_identity_client")}
local Config={}
for _,client in ipairs({"retail","forever"}) do for _,spec in ipairs(specs) do
 local id=client.."_"..spec;local cfg={}
 for k,v in pairs(bool_defaults) do cfg[k]=C.menu.checkbox(v,"pt100_"..id.."_"..k) end
 for k,v in pairs(num_defaults) do local hi=k=="mode" and #modes or k=="spec" and 4 or k=="client" and 3 or 100;cfg[k]=C.menu.slider_int(1,hi,v,"pt100_"..id.."_"..k) end
 Config[id]=cfg
end end
local function settings() return Config[(State.client or "retail").."_"..(State.spec or State.view)] end
function Settings.get(k) local x=Identity[k] or settings()[k];return x and x:get() end
function Settings.set(k,v) local x=Identity[k] or settings()[k];if x then x:set(v) end end
local function detect_identity()
 local me=static(C.object_manager,"get_local_player");if not alive(me) or unit(me,"get_class")~=5 then return nil,nil,"Waiting for a living priest" end
 local v=tostring(static(C,"get_game_version") or ""):lower()
 local client=v:find("forever",1,true) or v:find("1.60",1,true);client=client and "forever" or ((v=="retail" or v=="midnight" or v:find("11.",1,true) or v:find("12.",1,true)) and "retail" or nil)
 -- Client overrides are private to the active profile; they never patch shared APIs.
 local override=Settings.get("client");if override==2 then client="retail" elseif override==3 then client="forever" end
 if not client then return nil,nil,"Client unknown: choose Retail or WoW Forever in Settings" end
 local specid=tonumber(static(C.spell_book,"get_specialization_id"));local spec=({[256]="discipline",[257]="holy",[258]="shadow"})[specid]
 if client=="forever" then
  -- Tree clients have no Retail specialization IDs. Unique learned talents are decisive.
  local matches={};if resolve("penance") then matches[#matches+1]="discipline" end
  if known(15473) or resolve("vampiric_embrace") then matches[#matches+1]="shadow" end
  if resolve("binding_heal") or resolve("mending") or known(20711) then matches[#matches+1]="holy" end
  spec=#matches==1 and matches[1] or nil
 end
 local forced=Settings.get("spec");if forced and forced>1 then spec=specs[forced-1] end
 if not spec then return nil,client,"Talent identity ambiguous: select your spec override" end
 return spec,client,"Automatic client / learned talent identity"
end
local function detect_mode(me,target)
 local selected=modes[Settings.get("mode") or 1];if selected~="auto" then return selected,"Manual activity override" end
 local kind=tostring(static(C,"get_instance_type") or ""):lower()
 if kind=="arena" then return "arena","Arena instance" end
 if kind=="pvp" or kind=="battleground" then return "battleground","Battleground instance" end
 if static(C.delves,"is_in_delve")==true then return "delve","Host delve API" end
 if kind=="raid" then return "raid","Raid instance" end
 if kind=="party" then return static(C,"get_difficulty_id")==8 and "mythic_plus" or "dungeon","Party instance / difficulty" end
 if enemy(me,target) and unit(target,"is_player")==true then return "world_pvp","Hostile player target" end
 -- A hostile player attacking a party member also selects World PvP for healers.
 for _,u in pairs(static(C.object_manager,"get_visible_objects") or {}) do
  if enemy(me,u) and unit(u,"is_player")==true and unit(u,"is_in_combat")==true then
   local t=unit(u,"get_target");if same(t,me) or unit(t,"is_party_member")==true then return "world_pvp","Hostile player attacking group" end
  end
 end
 return "world_pve","Open world without active player conflict"
end
local Policies={
 world_pve={urgent=0,damage=85,dots=3,burst=12,group=3},
 world_pvp={urgent=8,damage=94,dots=3,burst=8,group=3,pvp=true},
 delve={urgent=5,damage=90,dots=4,burst=10,group=2},
 dungeon={urgent=2,damage=90,dots=5,burst=15,group=3},
 mythic_plus={urgent=5,damage=93,dots=6,burst=15,group=3},
 raid={urgent=0,damage=92,dots=5,burst=20,group=5},
 arena={urgent=12,damage=96,dots=2,burst=8,group=2,pvp=true},
 battleground={urgent=8,damage=94,dots=5,burst=10,group=4,pvp=true},
}
local function roster(me)
 local list,seen={},{};local function push(u) if alive(u) and not enemy(me,u) and distance(me,u)<=40 and (same(me,u) or static(C.graphics,"is_line_of_sight",me,u)==true) and not seen[guid(u)] then seen[guid(u)]=true;list[#list+1]=u end end
 push(me);for _,u in pairs(static(C.object_manager,"get_party_frames") or {}) do push(u) end
 for i=1,40 do push(static(C.object_manager,"get_object_from_guid","raid"..i)) end
 -- Include the player's own pet/companion if the host resolves it, never random friendly NPCs.
 if State.mode=="delve" then push(static(C.object_manager,"get_object_from_guid","pet")) end
 table.sort(list,function(a,b) return hp(a)<hp(b) end);return list
end
local function forecast(u)
 local id,t=guid(u),now();local h=hp(u);local old=State.prediction[id];local loss=0
 if old and t>old.t and t-old.t<2 then loss=math.max(0,(old.h-h)/(t-old.t));loss=0.65*(old.loss or 0)+0.35*loss end
 State.prediction[id]={h=h,t=t,loss=loss};return Settings.get("predictive") and math.max(0,h-loss*1.5) or h
end
local function incoming_ally_from(ctx)
 for _,e in ipairs(ctx.enemies or {}) do
  if unit(e,"is_casting_spell")==true then
   local u=unit(e,"get_active_spell_target")
   if alive(u) and not enemy(ctx.me,u) then for _,ally in ipairs(ctx.allies or {}) do if same(ally,u) then return ally end end end
  end
 end
end
local function snapshot(me,target)
 local ctx={me=me,target=target,allies=roster(me),enemies={},policy=Policies[State.mode] or Policies.world_pve,injured=0,critical=0,atoned=0}
 local seen={};local function push(u)
  if enemy(me,u) and distance(me,u)<=40 and not seen[guid(u)] then
   local ut=unit(u,"get_target");local engaged=unit(u,"is_in_combat")==true and (same(ut,me) or unit(ut,"is_party_member")==true or same(u,target))
   if engaged then seen[guid(u)]=true;ctx.enemies[#ctx.enemies+1]=u end
  end
 end
 push(target);for _,u in pairs(static(C.object_manager,"get_visible_objects") or {}) do push(u) end
 for _,u in ipairs(ctx.allies) do
  local predicted=forecast(u);if hp(u)<Settings.get("heal_at") then ctx.injured=ctx.injured+1 end
  if predicted<Settings.get("emergency")+ctx.policy.urgent then ctx.critical=ctx.critical+1 end
  if aura(u,194384,false,true)>3 then ctx.atoned=ctx.atoned+1 end
 end
 local incoming=incoming_ally_from(ctx);local best,best_score=ctx.allies[1] or me,-999
 for _,u in ipairs(ctx.allies) do
  local p=State.prediction[guid(u)] or {h=hp(u),loss=0};local projected=Settings.get("predictive") and math.max(0,p.h-p.loss*1.5) or p.h
  local score=100-projected+(same(u,incoming) and 18 or 0)+(same(u,me) and 2 or 0)
  if score>best_score then best,best_score=u,score end
 end
 ctx.low=best;ctx.lowhp=hp(best);ctx.incoming=incoming;ctx.predicted=State.prediction[guid(best)] or {h=ctx.lowhp,loss=0}
 local p=ctx.predicted;ctx.urgent=(Settings.get("predictive") and math.max(0,p.h-p.loss*1.5) or p.h)<Settings.get("emergency")+ctx.policy.urgent
 return ctx
end
local function cast(k,target,reason,ground,major)
 local me=State.me;local id=resolve(k);local t=now()
 if not id or not alive(target) or casting(me) or t<State.last_cast+0.12 or t<(State.backoff[k] or 0) then return false end
 if major and t<State.cd_lock then return false end
 if hard[k] and unit(me,"is_moving")==true then return false end
 if static(C.spell_book,"is_usable_spell",id)==false then return false end
 local charges=tonumber(static(C.spell_book,"get_spell_charge",id)) or 0
 if charges==0 and (tonumber(static(C.spell_book,"get_spell_cooldown",id)) or 999)>0.05 then return false end
 if (tonumber(static(C.spell_book,"get_global_cooldown")) or 0)>0.05 then return false end
 local check=helper and unit(helper,ground and "is_spell_castable_position" or "is_spell_castable",id,me,target,ground and position(target) or false,false)
 if check~=true then
  -- Fail closed if helper is unavailable; never replace range/LoS checks with a guessed cast.
  State.reason="Waiting for spell helper / castability";return false
 end
 local accepted=ground and static(C.input,"cast_position_spell",id,position(target)) or static(C.input,"cast_target_spell",id,target)
 State.backoff[k]=t+(accepted==true and 0.8 or 0.4)
 if accepted==true then
  State.last_cast=t;State.last_action=(Names[k] or k)..": "..reason;State.accepted=State.accepted+1
  if major then State.cd_lock=t+5 end
  if healing_spell[k] then State.heal_last=k end
  event("cast",State.last_action);return true
 end
 return false
end
local function attempt(k,u,why,ground,major) return cast(k,u,why,ground,major) end
local function ttd(u)
 local x=State.prediction[guid(u)];if not x or x.loss<=0.1 then return 999 end;return hp(u)/x.loss
end
local protected_cc={118,28272,28271,61305,6770,20066,5782,8122,2094,3355,2637,115078,51514,710}
local immune={642,45438,186265,33786,47585}
local function protected(u) for _,id in ipairs(protected_cc) do if aura(u,id,true)>0 then return true end end;for _,id in ipairs(immune) do if aura(u,id,false)>0 then return true end end;return false end
local function dispel(ctx)
 if not Settings.get("dispel") then return false end
 for _,u in ipairs(ctx.allies) do
  local magic,disease,blocked=false,false,false
  for _,a in pairs(unit(u,"get_debuffs") or {}) do
   if a.buff_id==30108 or a.buff_id==34914 or a.buff_id==33763 then blocked=true end
   local bt=require("common/enums").buff_type or {}
   if a.type==bt.MAGIC then magic=true elseif a.type==bt.DISEASE then disease=true end
  end
  -- UA and Vampiric Touch are deliberately left for manual dispels in PvP.
  if not blocked then
   if State.client=="retail" and State.spec~="shadow" and (magic or disease) and attempt("purify",u,"Friendly cleanse") then return true end
   if State.client=="forever" and magic and attempt("dispel_magic",u,"Forever magic cleanse") then return true end
   if disease and (attempt("cure_disease",u,"Disease cleanse") or attempt("abolish_disease",u,"Disease cleanse")) then return true end
  end
 end
 return false
end
local function utility(ctx)
 if Settings.get("interrupts") then for _,u in ipairs(ctx.enemies) do
  if not protected(u) and unit(u,"is_casting_spell")==true and unit(u,"is_active_spell_interruptable")==true and attempt("silence",u,"Interrupt active cast") then return true end
 end end
 -- CC is opt-in, used defensively only, never as an uncontrolled arena opener.
 if ctx.policy.pvp and Settings.get("pvp_cc") and hp(ctx.me)<60 then for _,u in ipairs(ctx.enemies) do
  if unit(u,"is_player")==true and same(unit(u,"get_target"),ctx.me) and not protected(u) and distance(ctx.me,u)<8 then
   if attempt("horror",u,"Peel attacker") then return true end
   if has(u,"pain",true)==0 and has(u,"vampiric_touch",true)==0 and attempt("scream",ctx.me,"Emergency peel") then return true end
  end
 end end
 return false
end
local function defense(ctx)
 if not Settings.get("defensives") then return false end
 local h=hp(ctx.me);local threshold=Settings.get("defensive_at")+ctx.policy.urgent
 if h<threshold and attempt("desperate_prayer",ctx.me,"Self emergency recovery",false,true) then return true end
 if h<threshold-10 and attempt("dispersion",ctx.me,"Critical self survival",false,true) then return true end
 if h<threshold and has(ctx.me,"shield")==0 and attempt("shield",ctx.me,"Self survival shield") then return true end
 return false
end
local function heal_forever(ctx)
 local u=ctx.low;local h=ctx.lowhp
 if ctx.urgent then
  if has(u,"shield")==0 and aura(u,6788,true)==0 and attempt("shield",u,"Forever emergency absorb") then return true end
  if attempt("penance",u,"Forever direct emergency healing") then return true end
  if attempt("flash_heal",u,"Forever emergency direct heal") then return true end
 end
 if h<Settings.get("heal_at") then
  if (ctx.injured>=2 or ctx.incoming) and has(u,"mending")==0 and attempt("mending",u,"Forever reactive group healing") then return true end
  if ctx.injured>=ctx.policy.group and Settings.get("aoe") then
   if Settings.get("cooldowns") and attempt("inner_focus",ctx.me,"Prepare efficient group healing") then return true end
   if attempt("circle",u,"Forever group recovery") or attempt("prayer_healing",u,"Forever party healing") then return true end
  end
  if h<75 and attempt("penance",u,"Forever efficient direct healing") then return true end
  if not same(u,ctx.me) and hp(ctx.me)<85 and attempt("binding_heal",u,"Forever dual-target recovery") then return true end
  if State.spec=="holy" and (State.heal_last=="heal" or State.heal_last=="flash_heal" or State.heal_last=="lesser_heal") and has(u,"renew")==0 and attempt("renew",u,"Forever Litany spell-family alternation") then return true end
  if has(u,"renew")==0 and attempt("renew",u,"Forever sustained recovery") then return true end
  local key=h<60 and "flash_heal" or "heal"
  if State.spec=="holy" and State.heal_last=="renew" and Settings.get("cooldowns") and attempt("inner_focus",ctx.me,"Prepare Litany direct heal") then return true end
  if attempt(key,u,"Forever direct healing") then return true end
  if attempt("lesser_heal",u,"Low-level healing fallback") then return true end
 end
 return false
end
local function incoming_ally(ctx) return ctx.incoming or incoming_ally_from(ctx) end
local function clustered_injured(ctx,radius)
 local best,count=ctx.low,0
 for _,center in ipairs(ctx.allies) do local n=0;for _,u in ipairs(ctx.allies) do if hp(u)<Settings.get("heal_at") and distance(center,u)<=radius then n=n+1 end end;if n>count then best,count=center,n end end
 return best,count
end
local function discipline(ctx)
 local u=ctx.low
 if ctx.urgent then
  if Settings.get("cooldowns") and attempt("pain_suppression",u,"Critical ally protection",false,true) then return true end
  if has(u,"shield")==0 and attempt("void_shield",u,"Emergency void absorb") then return true end
  if has(u,"shield")==0 and attempt("shield",u,"Emergency absorb") then return true end
  if attempt("penance",u,"Direct emergency healing") or attempt("flash_heal",u,"Direct emergency healing") then return true end
 end
 if ctx.injured>=ctx.policy.group and Settings.get("aoe") then
  local center,n=clustered_injured(ctx,6)
  if Settings.get("cooldowns") and ctx.critical>=2 and n>=ctx.policy.group and attempt("barrier",center,"Clustered critical damage",true,true) then return true end
  if ctx.atoned<math.min(ctx.policy.group,#ctx.allies) and attempt("radiance",u,"Group Atonement setup") then return true end
  local ramp_need=State.mode=="raid" and math.min(8,#ctx.allies) or math.min(4,#ctx.allies)
  if Settings.get("cooldowns") and ctx.atoned>=ramp_need and ctx.injured>=ctx.policy.group and attempt("evangelism",ctx.me,"Extend prepared Atonement ramp",false,true) then return true end
  if Settings.get("cooldowns") and ctx.critical>=2 and attempt("ultimate_penitence",u,"Critical group recovery",false,true) then return true end
 end
 if ctx.lowhp<Settings.get("heal_at") then
  if aura(u,194384,false,true)<3 and has(u,"shield")==0 and attempt("shield",u,"Apply Atonement to injured ally") then return true end
  if ctx.lowhp<65 and attempt("flash_heal",u,"Spot heal outside Atonement window") then return true end
 end
 if Settings.get("predictive") then local ally=incoming_ally(ctx)
  if ally and has(ally,"shield")==0 and attempt("shield",ally,"Incoming targeted cast protection") then return true end
 end
 return false
end
local function cluster(ctx,radius)
 local best,count=ctx.low,0
 for _,center in ipairs(ctx.allies) do local n=0;for _,u in ipairs(ctx.allies) do if hp(u)<Settings.get("heal_at") and distance(center,u)<=radius then n=n+1 end end;if n>count then best,count=center,n end end
 return best,count
end
local function holy(ctx)
 local u=ctx.low
 if ctx.urgent then
  if Settings.get("cooldowns") and attempt("guardian_spirit",u,"Critical ally protection",false,true) then return true end
  if attempt("serenity",u,"Emergency Holy Word") or attempt("flash_heal",u,"Emergency spot heal") then return true end
 end
 if ctx.lowhp<80 and attempt("serenity",u,"Efficient Holy Word recovery") then return true end
 if (ctx.injured>=2 or ctx.incoming) and has(u,"mending")==0 and attempt("mending",u,"Maintain Prayer of Mending") then return true end
 if ctx.injured>=ctx.policy.group and Settings.get("aoe") then
  local center,n=cluster(ctx,10)
  if n>=ctx.policy.group and attempt("sanctify",center,"Clustered group recovery",true) then return true end
  if attempt("circle",u,"Group recovery") then return true end
  if Settings.get("cooldowns") and ctx.critical>=3 and attempt("hymn",ctx.me,"Widespread critical damage",false,true) then return true end
  if Settings.get("cooldowns") and ctx.critical>=2 and attempt("apotheosis",ctx.me,"Restore Holy Word recovery",false,true) then return true end
  if attempt("halo",ctx.me,"Anticipated group healing and damage") or attempt("divine_star",center,"Clustered group healing",true) then return true end
  if State.mode~="raid" and attempt("prayer_healing",u,"Sustained dungeon group recovery") then return true end
 end
 if ctx.lowhp<Settings.get("heal_at") then
  if unit(ctx.me,"is_moving")==true and has(u,"renew")==0 and attempt("renew",u,"Moving recovery") then return true end
  if attempt(ctx.lowhp<65 and "flash_heal" or "heal",u,"Holy Word cooldown recovery") then return true end
 end
 return false
end
local function damage(ctx)
 local target=ctx.target;if not enemy(ctx.me,target) or protected(target) then return false end
 if not unit(ctx.me,"is_in_combat") or unit(target,"is_in_combat")~=true then return false end
 if State.spec~="shadow" then
  local disc_pve=State.spec=="discipline" and State.client=="retail" and not ctx.policy.pvp and State.mode~="raid"
  local floor=disc_pve and ctx.atoned>0 and 68 or math.max(Settings.get("damage_above"),ctx.policy.damage)
  if ctx.urgent or ctx.lowhp<floor or mana(ctx.me)<Settings.get("mana_reserve") then return false end
  if has(target,"holy_fire",true,true)<2 and attempt("holy_fire",target,"Holy damage synergy") then return true end
  if has(target,"pain",true,true)<2 and attempt("pain",target,"Sustained damage / Atonement") then return true end
  if State.spec=="discipline" and attempt("mind_blast",target,"Atonement burst damage") then return true end
  if attempt("penance",target,"Offensive Penance") or attempt("smite",target,"Safe damage window") then return true end
  return false
 end
 if State.client=="forever" then
  if hp(target)<20 and hp(ctx.me)>55 and attempt("death",target,"Forever execute with self-health reserve") then return true end
  if has(target,"pain",true,true)<3 and attempt("pain",target,"Forever Shadow DoT") then return true end
  if ttd(target)>8 and has(target,"plague",true,true)<3 and attempt("plague",target,"Forever learned disease DoT") then return true end
  if (hp(ctx.me)<85 or ctx.injured>0 or ttd(target)>20) and has(target,"vampiric_embrace",true,true)==0 and attempt("vampiric_embrace",target,"Forever sustain window") then return true end
  if attempt("mind_blast",target,"Forever Shadow burst") or attempt("mind_flay",target,"Forever Shadow filler") then return true end
  return false
 end
 local insanity,max_insanity=power(ctx.me,13);local spend=resolve("shadow_word_madness") and "shadow_word_madness" or "plague"
 if hp(target)<20 and hp(ctx.me)>55 and attempt("death",target,"Shadow execute") then return true end
 local dots_up=has(target,"vampiric_touch",true,true)>0 and has(target,"pain",true,true)>0
 if max_insanity>0 and (max_insanity-insanity<=35 or has(ctx.me,"voidform")>0) and attempt(spend,target,"Prevent Insanity overflow") then return true end
 local aoe_safe=true;for _,u in pairs(static(C.object_manager,"get_visible_objects") or {}) do
  if enemy(ctx.me,u) and distance(target,u)<10 and (protected(u) or unit(u,"is_in_combat")~=true) then aoe_safe=false;break end
 end
 if Settings.get("aoe") and aoe_safe and #ctx.enemies>=Settings.get("aoe_count") then
  if attempt("tentacle_slam",target,"Apply Midnight DoTs to engaged cluster") or attempt("shadow_crash",target,"Engaged enemy cluster",true) then return true end
 end
 if ttd(target)>12 and has(target,"vampiric_touch",true,true)<4 and attempt("vampiric_touch",target,"Maintain Vampiric Touch") then return true end
 if has(target,"pain",true,true)<3 and attempt("pain",target,"Maintain Shadow Word: Pain") then return true end
 if Settings.get("multidot") and Settings.get("aoe") and not ctx.policy.pvp then
  local cap=math.min(Settings.get("max_dots"),ctx.policy.dots);local n=0
  for _,u in ipairs(ctx.enemies) do if not protected(u) and ttd(u)>12 then n=n+1;if n<=cap and has(u,"vampiric_touch",true,true)<4 and attempt("vampiric_touch",u,"Bounded durable-target multidot") then return true end end end
 end
 if Settings.get("cooldowns") and dots_up and ttd(target)>ctx.policy.burst then
  if attempt("mindbender",target,"Prepare burst pet") or attempt("fiend",target,"Prepare burst pet") then return true end
  if has(ctx.me,"voidform")==0 and (attempt("voidform",ctx.me,"Learned Midnight burst",false,true) or attempt("void_eruption",target,"Voidform burst",false,true) or attempt("dark_ascension",ctx.me,"Dark Ascension burst",false,true)) then return true end
  if (aura(ctx.me,194249,false)>0 or aura(ctx.me,391109,false)>0 or has(ctx.me,"voidform")>0) and attempt("power_infusion",ctx.me,"Align with active burst",false,true) then return true end
 end
 if attempt("void_bolt",target,"Voidform generator") then return true end
 if has(target,spend,true,true)<2 and attempt(spend,target,"Maintain Insanity spender") then return true end
 if has(target,spend,true,true)>2.5 and attempt("void_torrent",target,"Full DoT channel window") then return true end
 if attempt("tentacle_slam",target,"Learned Midnight generator") or attempt("void_blast",target,"Learned Voidweaver generator") or attempt("mind_blast",target,"Shadow generator") or attempt("void_volley",target,"Learned Midnight charge") or attempt("mind_flay_insanity",target,"Empowered filler") or attempt("mind_flay",target,"Shadow filler") then return true end
 return false
end
local function maintenance(ctx)
 if not Settings.get("buffs") or unit(ctx.me,"is_in_combat")==true then return false end
 if State.spec=="shadow" and has(ctx.me,"shadowform")==0 and attempt("shadowform",ctx.me,"Maintain Shadowform") then return true end
 if State.client=="forever" and has(ctx.me,"inner_fire")==0 and attempt("inner_fire",ctx.me,"Forever armor buff") then return true end
 if has(ctx.me,"fortitude")==0 and attempt("fortitude",ctx.me,"Maintain Fortitude") then return true end
 return false
end
local function tick()
 local t=now();if t<State.next_tick then return end;State.next_tick=t+0.10
 State.me=static(C.object_manager,"get_local_player")
 if t-State.started<6 then State.reason="Waiting for client spell tables";return end
 if t>=State.next_identity then
  State.next_identity=t+1;scan_book();local s,c,why=detect_identity()
  if s~=State.spec or c~=State.client then reset_runtime();event("profile",tostring(c).." / "..tostring(s)) end
  State.spec,State.client=s,c;if s then State.view=s end;State.reason=why
 end
 if not State.spec or not alive(State.me) or unit(State.me,"get_class")~=5 then return end
 if not Settings.get("enabled") then State.reason="Paused";return end
 if static(C,"is_textbox_focused")==true or unit(State.me,"is_mounted")==true then State.reason="Manual input / mounted";return end
 local target=static(C.object_manager,"get_object_from_guid","target") or unit(State.me,"get_target")
 local m,why=detect_mode(State.me,target);if m~=State.mode then State.mode=m;State.prediction={};event("mode",m..": "..why) end
 State.mode_reason=why
 if casting(State.me) then State.reason="Preserving current cast / channel";return end
 local ctx=snapshot(State.me,target);State.allies=#ctx.allies;State.enemies=#ctx.enemies;State.lowhp=ctx.lowhp;State.atoned=ctx.atoned;State.reason="Evaluating "..State.spec.." / "..State.mode
 for _,u in ipairs(ctx.enemies) do forecast(u) end
 if defense(ctx) or utility(ctx) then return end
 if Settings.get("healing") then
  if State.client=="forever" then if heal_forever(ctx) then return end
  elseif State.spec=="discipline" then if discipline(ctx) then return end
  elseif State.spec=="holy" then if holy(ctx) then return end
  elseif ctx.urgent and (attempt("shield",ctx.low,"Shadow emergency support") or attempt("flash_heal",ctx.low,"Shadow emergency support")) then return end
 end
 if dispel(ctx) then return end
 if Settings.get("damage") and damage(ctx) then return end
 maintenance(ctx)
end

